	return oldNodeCIDRs, allocated, nil
}", "newString": "	var (
		v4RevertFunc, v6RevertFunc revert.RevertFunc
		v4Err, v6Err               error
		v4Allocated, v6Allocated   bool
	)

	// The node might want to allocate a new IPv4 podCIDR but it already
	// has a IPv6 podCIDR. We will only allocate new podCIDRs if
	// canAllocateIPv4PodCIDRs is set to true. It's fine that we don't allocate
	// it now since this node will be put into the map of nodes that require
	// to be allocated in the future.
	if canAllocateIPv4PodCIDRs && len(n.v4CIDRAllocators) != 0 {
		if len(v4CIDR) != 0 {
			v4RevertFunc, v4Err = allocateIPNet(v4AllocatorType, n.v4CIDRAllocators, v4CIDR)
		} else {
			// If the node does not have an IP address assigned to it, we need
			// to allocate it because we have allocators available.
			var newv4CIDR *net.IPNet
			v4RevertFunc, newv4CIDR, v4Err = allocateFirstFreeCIDR(n.v4CIDRAllocators)
			if v4Err == nil {
				v4CIDR = append(v4CIDR, newv4CIDR)
			}
		}
		if v4Err == nil {
			oldNodeCIDRs.v4PodCIDRs = v4CIDR
			n.logger.Debug(
				"Allocated v4CIDR",
				logfields.NodeName, nodeName,
			)
			v4Allocated = true
		}
	}

	// The node might want to allocate a new IPv6 podCIDR but it already
	// has a IPv4 podCIDR. We will only allocate new podCIDRs if
	// canAllocateIPv6PodCIDRs is set to true. It's fine that we don't allocate
	// it now since this node will be put into the map of nodes that require
	// to be allocated in the future.
	if canAllocateIPv6PodCIDRs && len(n.v6CIDRAllocators) != 0 {
		if len(v6CIDR) != 0 {
			v6RevertFunc, v6Err = allocateIPNet(v6AllocatorType, n.v6CIDRAllocators, v6CIDR)
		} else {
			// If the node does not have an IP address assigned to it, we need
			// to allocate it because we have allocators available.
			var newv6CIDR *net.IPNet
			v6RevertFunc, newv6CIDR, v6Err = allocateFirstFreeCIDR(n.v6CIDRAllocators)
			if v6Err == nil {
				v6CIDR = append(v6CIDR, newv6CIDR)
			}
		}
		if v6Err == nil {
			oldNodeCIDRs.v6PodCIDRs = v6CIDR
			n.logger.Debug(
				"Allocated v6CIDR",
				logfields.NodeName, nodeName,
			)
			v6Allocated = true
		}
	}

	// Report the first error encountered while allocating a family's CIDR.
	err = v4Err
	if err == nil {
		err = v6Err
	}

	if err != nil {
		// A CIDR that is 'already allocated' by another node is a soft conflict:
		// the requested CIDR for that family cannot be occupied, but the other
		// family may still have been allocated successfully. Any other error
		// (e.g. the allocator being full or not configured) is a hard failure.
		var errCIDRAllocated *ErrCIDRAllocated
		v4Conflict := v4Err != nil && errors.As(v4Err, &errCIDRAllocated)
		v6Conflict := v6Err != nil && errors.As(v6Err, &errCIDRAllocated)
		hardFailure := (v4Err != nil && !v4Conflict) || (v6Err != nil && !v6Conflict)

		// Keep a partial allocation only when the failure is exclusively due to
		// an 'already allocated' conflict on one family and the other family was
		// successfully allocated.
		if !hardFailure && (v4Allocated || v6Allocated) {
			// Drop the conflicting family so that only the successfully
			// allocated CIDR(s) are retained and reported.
			if v4Conflict {
				oldNodeCIDRs.v4PodCIDRs = nil
			}
			if v6Conflict {
				oldNodeCIDRs.v6PodCIDRs = nil
			}
			// The successfully allocated CIDRs remain occupied in the pool and
			// the node is stored so they are not handed out to another node.
			n.nodes[nodeName] = oldNodeCIDRs
			return oldNodeCIDRs, true, err
		}

		// Nothing could be kept: revert any successful allocation so that no
		// CIDR remains occupied and the node is not stored.
		var revertStack revert.RevertStack
		if v4RevertFunc != nil {
			revertStack.Push(v4RevertFunc)
		}
		if v6RevertFunc != nil {
			revertStack.Push(v6RevertFunc)
		}
		revertStack.Revert()
		return nil, false, err
	}

	// Only add the node to the list of nodes allocated if there wasn't
	// an error allocating the CIDR
	n.nodes[nodeName] = oldNodeCIDRs

	return oldNodeCIDRs, v4Allocated || v6Allocated, nil
